import React from "react";
import {AppBar,Toolbar,styled} from '@mui/material';

const Head = styled(AppBar)`
    background : #000066;
    height : 9vh`


const Header = ()=>{
    const logo = "./icons8-codepen-50.svg"
    return(
       <Head>
        <Toolbar>
            <img src="codepen/src/components/icons8-codepen-50.svg" alt="Code Pen"/>
        </Toolbar>
       </Head>
    )
}

export default Header;
